example.programlisting:
import oorexx

with oorexx.Interpreter() as rexx:
    try:
        rexx.eval("1 / 0")
    except oorexx.RexxError as e:
        print(type(e).__name__, isinstance(e, RuntimeError))
        print(e)
    item = rexx.routine("use arg d, k; return d[k]")
    try:
        item({}, "nope")                # Python's KeyError, through Rexx
    except KeyError as e:
        print("KeyError", e)
